//
//  HDR Tone Mapping
//  Native Metal Shader - Cinematic Color Grading
//

#include <metal_stdlib>
using namespace metal;

struct Uniforms {
    float4x4 MVP;
    float4 OutputSize;
    float4 SourceSize;
    float4 OriginalSize;
    uint FrameCount;
    float exposure;
    float contrast;
    float saturation;
    float tonemap_mode;
};

struct VertexIn {
    float4 position [[attribute(0)]];
    float2 texCoord [[attribute(1)]];
};

struct VertexOut {
    float4 position [[position]];
    float2 texCoord;
};

vertex VertexOut main0(
    VertexIn in [[stage_in]],
    constant Uniforms &uniforms [[buffer(0)]]
)
{
    VertexOut out;
    out.position = uniforms.MVP * in.position;
    out.texCoord = in.texCoord;
    return out;
}

// Reinhard tone mapping
float3 reinhardTonemap(float3 color) {
    return color / (1.0 + color);
}

// Filmic tone mapping (Uncharted 2)
float3 filmicTonemap(float3 x) {
    float A = 0.15;
    float B = 0.50;
    float C = 0.10;
    float D = 0.20;
    float E = 0.02;
    float F = 0.30;
    return ((x * (A * x + C * B) + D * E) / (x * (A * x + B) + D * F)) - E / F;
}

// ACES tone mapping
float3 acesTonemap(float3 x) {
    float a = 2.51;
    float b = 0.03;
    float c = 2.43;
    float d = 0.59;
    float e = 0.14;
    return clamp((x * (a * x + b)) / (x * (c * x + d) + e), 0.0, 1.0);
}

// Hable tone mapping (Uncharted 2)
float3 hableTonemap(float3 color) {
    float exposureBias = 2.0;
    float3 curr = filmicTonemap(color * exposureBias);
    float3 whiteScale = 1.0 / filmicTonemap(float3(11.2));
    return curr * whiteScale;
}

fragment float4 fragment_main(
    VertexOut in [[stage_in]],
    texture2d<float> sourceTexture [[texture(0)]],
    constant Uniforms &uniforms [[buffer(0)]]
)
{
    constexpr sampler textureSampler(
        mag_filter::linear,
        min_filter::linear,
        address::clamp_to_edge
    );

    float3 color = sourceTexture.sample(textureSampler, in.texCoord).rgb;

    // Apply exposure
    color *= pow(2.0, uniforms.exposure);

    // Select tone mapping operator
    int mode = int(uniforms.tonemap_mode);
    if (mode == 0) {
        // Reinhard
        color = reinhardTonemap(color);
    } else if (mode == 1) {
        // Filmic (Uncharted 2)
        color = hableTonemap(color);
    } else if (mode == 2) {
        // ACES
        color = acesTonemap(color);
    } else {
        // Linear (clamp)
        color = clamp(color, 0.0, 1.0);
    }

    // Contrast
    color = (color - 0.5) * uniforms.contrast + 0.5;
    color = clamp(color, 0.0, 1.0);

    // Saturation
    float luminance = dot(color, float3(0.299, 0.587, 0.114));
    color = mix(float3(luminance), color, uniforms.saturation);

    return float4(color, 1.0);
}

